Tile("key-check", {
  css: ".kc{font-size:20px;line-height:1.35} .kc h3{margin:0 0 6px} .kc .ok{color:#7fd67f} .kc .bad{color:#ff7a7a} .kc small{color:var(--dim)}",
  cls: "kc",
  render(el){
    const A = "https://httpbin.org/anything?from=countertop", B = "https://postman-echo.com/get?from=countertop",
      R = "https://httpbin.org/redirect-to?url=" + encodeURIComponent(B + "&via=redirect");
    const a = this.fetch(A, 60), b = this.fetch(B, 60), r = this.fetch(R, 60);
    const head = (j, name) => { const h = (j && j.headers) || {}; for (const k in h) if (k.toLowerCase() === name) return h[k]; return undefined; };
    // what the site saw: the key arrived but the tile only sees it blanked out, or it never arrived
    const got = v => v === undefined ? "not sent" : v === "********" ? "arrived, hidden from the tile" : "VISIBLE TO THE TILE: " + v;
    const good = (v, want) => (want ? v === "********" : v === undefined) ? "ok" : "bad";
    const row = (label, url, j, want) => {
      if (!j) return "<div>" + this.esc(label) + ": <small>" + this.esc(this.fetchError(url) || "loading…") + "</small></div>";
      const h = head(j, "x-api-key"), q = (j.args || {}).token;
      return "<div class=" + (good(h, want) === "ok" && good(q, want) === "ok" ? "ok" : "bad") + ">" + this.esc(label) +
        ": header key " + this.esc(got(h)) + "; address key " + this.esc(got(q)) + "</div>";
    };
    el.innerHTML = "<h3>" + this.esc(this.name) + "</h3>" +
      "<div>Header key saved: <b>" + (this.s.key === true ? "yes" : "no") + "</b>, address key saved: <b>" + (this.s.token === true ? "yes" : "no") + "</b></div>" +
      "<div><small>What this tile's code sees for the keys: " + this.esc(JSON.stringify([this.s.key, this.s.token])) + "</small></div>" +
      row("httpbin.org (the keys' site)", A, a, true) + row("postman-echo.com (another site)", B, b, false) + row("redirect to postman-echo.com", R, r, false);
  }
});
